import { h } from '@stencil/core';
import { newSpecPage } from '@stencil/core/testing';
import { ScLineItemTax } from '../sc-line-item-tax';

describe('sc-line-item-tax', () => {
  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScLineItemTax],
      html: `<sc-line-item-tax></sc-line-item-tax>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('renders one row per tax breakdown entry', async () => {
    const page = await newSpecPage({
      components: [ScLineItemTax],
      template: () => (
        <sc-line-item-tax
          order={
            {
              tax_status: 'calculated',
              tax_amount: 1200,
              tax_exclusive_amount: 1200,
              tax_inclusive_amount: 0,
              tax_label: 'Tax',
              tax_breakdown: [
                { tax_rate: 5, tax_label: 'GST', taxable_amount: 10000, tax_amount: 500, tax_display_amount: '$5.00', taxable_display_amount: '$100.00' },
                { tax_rate: 7, tax_label: 'PST', taxable_amount: 4000, tax_amount: 700, tax_display_amount: '$7.00', taxable_display_amount: '$40.00' },
              ],
            } as any
          }
        ></sc-line-item-tax>
      ),
    });

    // With stacked rows, each carries its rate and base so the split is legible.
    const rows = page.root.shadowRoot.querySelectorAll('sc-line-item');
    expect(rows).toHaveLength(2);
    expect(rows[0].querySelector('[slot="description"]').textContent).toBe('Tax GST (5% on $100.00)');
    expect(rows[0].querySelector('[slot="price"]').textContent).toBe('$5.00');
    expect(rows[1].querySelector('[slot="description"]').textContent).toBe('Tax PST (7% on $40.00)');
    expect(rows[1].querySelector('[slot="price"]').textContent).toBe('$7.00');
  });

  it('keeps a single breakdown row plain', async () => {
    const page = await newSpecPage({
      components: [ScLineItemTax],
      template: () => (
        <sc-line-item-tax
          order={
            {
              tax_status: 'calculated',
              tax_amount: 500,
              tax_exclusive_amount: 500,
              tax_inclusive_amount: 0,
              tax_label: 'GST',
              tax_breakdown: [{ tax_rate: 5, tax_label: 'GST', taxable_amount: 10000, tax_amount: 500, tax_display_amount: '$5.00', taxable_display_amount: '$100.00' }],
            } as any
          }
        ></sc-line-item-tax>
      ),
    });

    const rows = page.root.shadowRoot.querySelectorAll('sc-line-item');
    expect(rows).toHaveLength(1);
    expect(rows[0].querySelector('[slot="description"]').textContent).toBe('Tax GST');
  });

  it('falls back to the single aggregate row without a breakdown', async () => {
    const page = await newSpecPage({
      components: [ScLineItemTax],
      template: () => (
        <sc-line-item-tax
          order={
            {
              tax_status: 'estimated',
              tax_amount: 500,
              tax_exclusive_amount: 500,
              tax_inclusive_amount: 0,
              tax_label: 'GST',
              tax_display_amount: '$5.00',
            } as any
          }
        ></sc-line-item-tax>
      ),
    });

    const rows = page.root.shadowRoot.querySelectorAll('sc-line-item');
    expect(rows).toHaveLength(1);
    expect(rows[0].querySelector('[slot="description"]').textContent).toBe('Tax Estimated GST');
    expect(rows[0].querySelector('[slot="price"]').textContent).toBe('$5.00');
  });

  it('marks rows as included for inclusive tax', async () => {
    const page = await newSpecPage({
      components: [ScLineItemTax],
      template: () => (
        <sc-line-item-tax
          order={
            {
              tax_status: 'calculated',
              tax_amount: 500,
              tax_exclusive_amount: 0,
              tax_inclusive_amount: 500,
              tax_label: 'VAT',
              tax_display_amount: '$5.00',
            } as any
          }
        ></sc-line-item-tax>
      ),
    });

    const row = page.root.shadowRoot.querySelector('sc-line-item');
    expect(row.querySelector('[slot="price"]')).toBeNull();
    expect(row.querySelector('[slot="price-description"]').textContent).toBe('($5.00 included)');
  });
});
